    private void btnReporteProfesoresActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnReporteProfesoresActionPerformed
        txtReporte.setText(controlador.reporteProfesores());
        txtReporte.setCaretPosition(0);
    }//GEN-LAST:event_btnReporteProfesoresActionPerformed

    private boolean esEstudiante() {
        return cmbTipo.getSelectedIndex() == 0;
    }

    // Solo deja escribir en los campos del tipo de persona elegido
    private void activarCampos() {
        boolean estudiante = esEstudiante();
        txtCodigo.setEnabled(estudiante);
        txtGrado.setEnabled(estudiante);
        txtCedula.setEnabled(!estudiante);
        txtArea.setEnabled(!estudiante);
        txtSalarioHora.setEnabled(!estudiante);
        txtHoras.setEnabled(!estudiante);
    }

    private void limpiar() {
        JTextField[] campos = {txtNombre, txtDireccion, txtTelefono, txtDia, txtMes, txtAnio,
            txtCodigo, txtGrado, txtCedula, txtArea, txtSalarioHora, txtHoras};
        for (JTextField campo : campos) {
            campo.setText("");
        }
        txtNombre.requestFocus();
    }

